const BANK_KEYWORD = 'EXAMPLEBANK';
// Este parser foi criado para UM único layout de fatura; para dar suporte a outro layout, altere BANK_KEYWORD e as regras de extração.
const MESES = { JAN:1, FEV:2, MAR:3, ABR:4, MAI:5, JUN:6, JUL:7, AGO:8, SET:9, OUT:10, NOV:11, DEZ:12 };
const brToFloat = v => parseFloat(v.replace(/\./g, '').replace(',', '.'));
const out = [];

for (const item of $input.all()) {
  const rawText = item.json.text || '';
  const lines = rawText.split('\n').map(l => l.trim()).filter(l => l.length > 0);

  const banco_detectado = rawText.toLowerCase().includes(BANK_KEYWORD.toLowerCase()) ? BANK_KEYWORD.toLowerCase() : 'desconhecido';
  const vencMatch = rawText.match(/Data de vencimento:\s*(\d{2})\s([A-ZÇ]{3})\s(\d{4})/);
  const totalMatch = rawText.match(/Total a pagar R\$\s*([\d\.,]+)/);
  const valorTotal = totalMatch ? brToFloat(totalMatch[1]) : null;

  const outrosMatch = rawText.match(/Outros lançamentos\s*([−\-])?\s*R\$\s*([\d\.,]+)/);
  let vencimentoISO = null, anoV = null, mesV = null;
  if (vencMatch) {
    anoV = parseInt(vencMatch[3]);
    mesV = MESES[vencMatch[2]];
    vencimentoISO = `${anoV}-${String(mesV).padStart(2, '0')}-${vencMatch[1]}`;
  }

  const transacoes = [];
  const pagamentosIgnorados = [];
  let inTransactions = false, currentDate = null, lastDescription = null;

  for (const line of lines) {
    if (line.startsWith('TRANSAÇÕES')) { inTransactions = true; continue; }
    if (!inTransactions) continue;
    if (line.startsWith('Pagamentos')) break;

    const dateMatch = line.match(/^(\d{2})\s([A-ZÇ]{3})$/);
    if (dateMatch) { currentDate = { dia: parseInt(dateMatch[1]), mesStr: dateMatch[2] }; continue; }
    if (line.startsWith('Conversão:') || line.startsWith('USD')) continue;

    // O PDF usa o sinal Unicode de menos (U+2212) antes de R$.
    const valueMatch = line.match(/([−\-])?\s*R\$\s*([\d\.,]+)/);
    if (valueMatch && currentDate) {
      const negativo = !!valueMatch[1];
      const valor = brToFloat(valueMatch[2]) * (negativo ? -1 : 1);
      const descricao = line.replace(/([−\-])?\s*R\$\s*([\d\.,]+)/, '').trim();
      const finalDescricao = descricao || lastDescription || 'Transação';

      // O pagamento da fatura anterior não representa uma despesa.
      if (negativo && /^pagamento/i.test(finalDescricao)) { pagamentosIgnorados.push(valor); continue; }

      const mes = MESES[currentDate.mesStr];
      const ano = mes > mesV ? anoV - 1 : anoV;
      const dataISO = `${ano}-${String(mes).padStart(2, '0')}-${String(currentDate.dia).padStart(2, '0')}`;
      transacoes.push({ date_iso: dataISO, description: finalDescricao, amount: valor });
      continue;
    }
    if (!line.includes('R$') && !line.startsWith('IOF')) lastDescription = line;
  }

  // Tarifas e juros podem aparecer somente no resumo da fatura.
  const somaAntes = transacoes.reduce((a, t) => a + t.amount, 0);
  const vOutros = outrosMatch ? brToFloat(outrosMatch[2]) * (outrosMatch[1] ? -1 : 1) : 0;
  // Inclua o encargo somente se ele explicar exatamente a diferença.
  if (outrosMatch && vencimentoISO && valorTotal !== null && Math.abs(valorTotal - somaAntes - vOutros) <= 0.01) {
    const v = vOutros;
    transacoes.push({ date_iso: vencimentoISO, description: 'Outros lançamentos (juros/encargos)', amount: v });
  }

  const somaCompras = Number(transacoes.reduce((a, t) => a + t.amount, 0).toFixed(2));
  const diferenca = valorTotal !== null ? Number((valorTotal - somaCompras).toFixed(2)) : null;

  out.push({ json: {
    banco_detectado,
    vencimento: vencimentoISO,
    valor_total: valorTotal,
    soma_compras: somaCompras,
    diferenca,
    pagamentos_ignorados: pagamentosIgnorados,
    total_transacoes_encontradas: transacoes.length,
    transacoes
  }});
}
return out;

// Não grave dados quando o total da fatura não confere.
const invalidos = $input.all().filter(i => {
  const j = i.json;
  return !j.vencimento || j.valor_total === null || Math.abs(j.diferenca) > 0.01 || j.banco_detectado === 'desconhecido';
});
if (invalidos.length) {
  throw new Error('Validação falhou: ' + invalidos.map(i =>
    `venc=${i.json.vencimento} total=${i.json.valor_total} soma=${i.json.soma_compras} dif=${i.json.diferenca}`).join(' | '));
}

return $input.all().map(i => {
  const j = i.json;
  const contagem = {};
  const transacoes = j.transacoes.map(t => {
    const k = `${t.date_iso}|${t.description}|${t.amount}`;
    contagem[k] = (contagem[k] || 0) + 1;   // Numera compras idênticas feitas no mesmo dia.
    return { data: t.date_iso, descricao: t.description, valor: t.amount, linha: contagem[k] };
  });
  return { json: { payload: JSON.stringify({
    usuario: 'sample_user',
    banco: j.banco_detectado,
    vencimento: j.vencimento,
    valor_total: j.valor_total,
    transacoes
  })}};
});

return $input.all().map(it => {
  const b = it.binary.data || {};
  return { json: { fileHash: `${b.fileName || 'unknown.pdf'}_${b.fileSize || 0}`, source: 'manual', fileName: b.fileName, fileSize: b.fileSize }, binary: it.binary };
});
